begin;
create temporary table five_feature_results(test text,passed boolean) on commit drop;
do $$
declare f uuid;s uuid;m uuid;d uuid;k uuid;b integer;staff bigint;oid bigint;n bigint;prev bigint;j jsonb;lim integer;cnt integer;oid2 bigint;c2 bigint;b2 integer;report_day date:=(now() at time zone 'Africa/Cairo')::date-1;
begin
 select branch_id,user_id into b,f from public.dlv_profiles where active and workflow_role='callcenter_followup' limit 1;
 select user_id into s from public.dlv_profiles where active and branch_id=b and workflow_role='supervisor' limit 1;
 select user_id into m from public.dlv_profiles where active and branch_id=b and workflow_role='manager' limit 1;
 select user_id into d from public.dlv_profiles where active and branch_id=b and workflow_role='driver' and b=any(allowed_branch_ids) limit 1;
 select user_id into k from public.dlv_profiles where active and branch_id=b and workflow_role='kitchen' limit 1;
 select id into staff from public.dlv_callcenter_staff where active and branch_id=b limit 1;
 perform set_config('request.jwt.claim.sub',m::text,true);j:=public.dlv_shift_summary(report_day,'full',b);prev:=(j->>'total')::bigint;
 perform set_config('request.jwt.claim.sub',f::text,true);
 oid:=public.dlv_create_order('QA5-'||substr(gen_random_uuid()::text,1,10),'Synthetic',null,null,null,null,b,staff);
 update public.dlv_orders set created_at=(report_day+time '10:00') at time zone 'Africa/Cairo' where id=oid;
 select coalesce(kitchen_minutes,25) into lim from public.dlv_branch_sla where branch_id=b;lim:=coalesce(lim,25);
 update public.dlv_orders set kitchen_received_at=now()-make_interval(mins=>lim+11) where id=oid;
 perform private.dlv_scan_stage_delays(b);
 if not exists(select 1 from public.dlv_notifications where order_id=oid and notification_type='stage_escalated_kitchen') then raise exception 'No manager escalation';end if;
 select count(*) into cnt from public.dlv_notifications where order_id=oid;
 perform private.dlv_scan_stage_delays(b);
 if (select count(*) from public.dlv_notifications where order_id=oid)<>cnt then raise exception 'Duplicate notification';end if;
 if exists(select 1 from public.dlv_notifications n join public.dlv_profiles p on p.user_id=n.user_id join public.dlv_branches h on h.id=p.branch_id join public.dlv_branches target on target.id=b where n.order_id=oid and not(p.role='admin' and p.workflow_role='admin') and h.company_id is distinct from target.company_id) then raise exception 'Cross-company notification';end if;
 insert into five_feature_results values('escalation_and_no_duplicate_or_cross_company_notifications',true);
 perform set_config('request.jwt.claim.sub',k::text,true);perform public.dlv_record_delay_action(oid,'QA kitchen followup');
 if not exists(select 1 from private.dlv_stage_followups where order_id=oid and action_by=k) then raise exception 'Action not attributed';end if;
 perform public.dlv_kitchen_forward(oid,null);
 perform set_config('request.jwt.claim.sub',s::text,true);perform public.dlv_supervisor_receive(oid,null);
 j:=public.dlv_suggest_drivers(oid);
 if jsonb_array_length(j)=0 or exists(select 1 from jsonb_array_elements(j) x where (x->>'active_orders')::int<0) then raise exception 'Suggestion invalid';end if;
 if exists(select 1 from jsonb_array_elements(j) x where x ? 'phone' or x ? 'lat' or x ? 'lng') then raise exception 'Suggestion privacy failure';end if;
 insert into five_feature_results values('suggestions_authorized_minimal_fields',true);
 perform public.dlv_assign_driver(oid,d,null);
 perform set_config('request.jwt.claim.sub',f::text,true);j:=public.dlv_order_dossier(oid);
 if (j->'order'->>'id')::bigint<>oid or jsonb_array_length(j->'events')<4 or jsonb_array_length(j->'delay_actions')<>1 then raise exception 'Dossier incomplete';end if;
 insert into five_feature_results values('dossier_timeline_and_delay_history',true);
 perform set_config('request.jwt.claim.sub',m::text,true);j:=public.dlv_shift_summary(report_day,'full',b);
 if (j->>'total')::bigint<>prev+1 or (j->'delays'->>'kitchen')::int<1 then raise exception 'Shift counts invalid';end if;
 if j::text like '%Synthetic%' then raise exception 'Customer details in report';end if;
 insert into five_feature_results values('shift_report_and_stage_delay_analysis_without_customer_details',true);
 perform set_config('request.jwt.claim.sub',d::text,true);
 begin perform public.dlv_order_dossier(oid);raise exception 'Driver got manager dossier';exception when raise_exception then if sqlerrm<>'غير مصرح' then raise;end if;end;
 begin perform public.dlv_shift_summary(report_day,'full',b);raise exception 'Driver got management report';exception when raise_exception then if sqlerrm<>'غير مصرح' then raise;end if;end;
 insert into five_feature_results values('restricted_roles_denied_management_endpoints',true);
 perform set_config('request.jwt.claim.sub',f::text,true);
 oid2:=public.dlv_create_order('QA5-ACTION-'||substr(gen_random_uuid()::text,1,8),null,null,null,null,null,b,staff);
 update public.dlv_orders set kitchen_received_at=now()-make_interval(mins=>lim+5) where id=oid2;
 perform private.dlv_scan_stage_delays(b);
 perform public.dlv_record_delay_action(oid2,'QA action before escalation');
 update public.dlv_orders set kitchen_received_at=now()-make_interval(mins=>lim+15) where id=oid2;
 perform private.dlv_scan_stage_delays(b);
 if exists(select 1 from public.dlv_notifications where order_id=oid2 and notification_type='stage_escalated_kitchen') then raise exception 'Escalated despite recorded action';end if;
 insert into five_feature_results values('recorded_action_suppresses_unattended_escalation',true);
 insert into public.dlv_companies(name,slug,active,onboarding_status) values('QA5 company','qa5-'||substr(gen_random_uuid()::text,1,10),true,'active') returning id into c2;
 select coalesce(min(id),0)-1 into b2 from public.dlv_branches;
 insert into public.dlv_branches(id,name,company_id) values(b2,'QA5 branch '||gen_random_uuid()::text,c2);
 update public.dlv_profiles set branch_id=b2,allowed_branch_ids=array[b2] where user_id=m;
 perform set_config('request.jwt.claim.sub',m::text,true);
 begin perform public.dlv_order_dossier(oid);raise exception 'Cross company dossier';exception when raise_exception then if sqlerrm<>'الطلب غير متاح' then raise;end if;end;
 begin perform public.dlv_suggest_drivers(oid);raise exception 'Cross company suggestion';exception when raise_exception then if sqlerrm<>'الطلب غير متاح' then raise;end if;end;
 begin perform public.dlv_shift_summary(report_day,'full',b);raise exception 'Cross company report';exception when raise_exception then if sqlerrm<>'فرع غير مصرح' then raise;end if;end;
 if exists(select 1 from public.dlv_list_stage_notifications() n where n.order_id in(oid,oid2)) then raise exception 'Cross company notification';end if;
 insert into five_feature_results values('all_new_read_endpoints_reject_second_company_access',true);
end $$;
select * from five_feature_results;
rollback;
